import { test, expect } from "@playwright/test";
import { ContactPage } from "../pages/contact.page";

test.describe("Customer Support — OWASP Juice Shop", () => {

  // @story:SCRUM-22
  // @ac:1
  // @design:D1
  // @type:functional
  // @technique:checklist-based
  test("AC-1 — Feedback form displays comment, rating and CAPTCHA fields", async ({ page }, testInfo) => {
    const contactPage = new ContactPage(page);

    await test.step("Given I navigate to \"/#/contact\"", async () => {
      // @bdd2pw lane=rule rule=rule-26
      await contactPage.goto();
    });

    await test.step("Then the page displays \"Comment\"", async () => {
      // @bdd2pw lane=rule rule=rule-50
      await expect(contactPage.page.getByText("Comment").first()).toBeVisible();
    });

    await test.step("And the page displays \"Rating\"", async () => {
      // @bdd2pw lane=rule rule=rule-50
      await expect(contactPage.page.getByText("Rating").first()).toBeVisible();
    });

    await test.step("And the page displays \"CAPTCHA\"", async () => {
      // @bdd2pw lane=rule rule=rule-50
      await expect(contactPage.page.getByText("CAPTCHA").first()).toBeVisible();
    });
  });

  // @story:SCRUM-22
  // @ac:2
  // @design:D2
  // @type:functional
  // @technique:boundary-value-analysis
  test("AC-2 — Submit is disabled when no fields are filled", async ({ page }, testInfo) => {
    const contactPage = new ContactPage(page);

    await test.step("Given I navigate to \"/#/contact\"", async () => {
      // @bdd2pw lane=rule rule=rule-26
      await contactPage.goto();
    });

    await test.step("Then the Submit button is disabled", async () => {
      await expect(contactPage.buttonToSendTheReviewButton).toBeDisabled();
    });
  });

  // @story:SCRUM-22
  // @ac:3
  // @design:D3
  // @type:functional
  // @technique:state-transition
  test("AC-3 — Submitting with correct CAPTCHA answer thanks the customer and clears the form", async ({ page }, testInfo) => {
    const contactPage = new ContactPage(page);

    await test.step("Given I navigate to \"/#/contact\"", async () => {
      // @bdd2pw lane=rule rule=rule-26
      await contactPage.goto();
    });

    await test.step("And I fill in the Comment field", async () => {
      await contactPage.fieldForEnteringTheCommentOrTheFeedbackInput.fill("This is a test comment for the feedback form.");
    });

    await test.step("And I read and solve the CAPTCHA", async () => {
      // Read the CAPTCHA expression from the page
      const captchaText = await contactPage.captchaCodeWhichMustBeSolved.textContent();
      expect(captchaText, "CAPTCHA expression should be present on the page").toBeTruthy();
      // Evaluate the arithmetic expression (only +, -, * operators used)
      // eslint-disable-next-line no-eval
      const answer = String(Function('"use strict"; return (' + captchaText!.trim() + ')')());
      await contactPage.fieldForTheResultOfTheCaptchaCodeInput.fill(answer);
    });

    await test.step("And I click Submit", async () => {
      await expect(contactPage.buttonToSendTheReviewButton).toBeEnabled();
      await contactPage.buttonToSendTheReviewButton.click();
    });

    await test.step("Then the page displays a thank you message", async () => {
      // After successful submission, a snack bar with "Thank you" appears
      await expect(contactPage.page.getByText("Thank you").first()).toBeVisible();
    });

    await test.step("And the form is cleared", async () => {
      // The comment field should be empty after successful submission
      await expect(contactPage.fieldForEnteringTheCommentOrTheFeedbackInput).toHaveValue("");
    });
  });

  // @story:SCRUM-22
  // @ac:4
  // @design:D4
  // @type:functional
  // @technique:equivalence-partitioning
  test("AC-4 — Submitting with wrong CAPTCHA answer is refused with a message", async ({ page }, testInfo) => {
    const contactPage = new ContactPage(page);

    await test.step("Given I navigate to \"/#/contact\"", async () => {
      // @bdd2pw lane=rule rule=rule-26
      await contactPage.goto();
    });

    await test.step("And I fill in the Comment field", async () => {
      await contactPage.fieldForEnteringTheCommentOrTheFeedbackInput.fill("Test feedback comment.");
    });

    await test.step("And I enter a wrong CAPTCHA answer", async () => {
      // Read the correct answer, then submit an obviously wrong one
      const captchaText = await contactPage.captchaCodeWhichMustBeSolved.textContent();
      expect(captchaText, "CAPTCHA expression should be present on the page").toBeTruthy();
      const correctAnswer = Function('"use strict"; return (' + captchaText!.trim() + ')')() as number;
      const wrongAnswer = String(correctAnswer + 1);
      await contactPage.fieldForTheResultOfTheCaptchaCodeInput.fill(wrongAnswer);
    });

    await test.step("And I click Submit", async () => {
      await expect(contactPage.buttonToSendTheReviewButton).toBeEnabled();
      await contactPage.buttonToSendTheReviewButton.click();
    });

    await test.step("Then an error message is displayed", async () => {
      // After wrong CAPTCHA, a snack bar with an error message should appear
      await expect(contactPage.page.getByText("Wrong answer to CAPTCHA").first()).toBeVisible();
    });
  });

  // @story:SCRUM-22
  // @design:D5
  // @type:accessibility
  // @technique:checklist-based
  test("AC-5 — Customer Feedback page passes accessibility checks", async ({ page }, testInfo) => {
    const contactPage = new ContactPage(page);

    await test.step("Given I navigate to \"/#/contact\"", async () => {
      // @bdd2pw lane=rule rule=rule-26
      await contactPage.goto();
    });

    await test.step("Then the page passes axe accessibility checks", async () => {
      // @bdd2pw lane=rule rule=rule-49
      const { default: AxeBuilder } = await import("@axe-core/playwright");
      const axeResults = await new AxeBuilder({ page: contactPage.page })
        .include("app-contact")
        .withTags(["wcag2a", "wcag2aa"])
        .analyze();
      expect(axeResults.violations.map((v) => v.id).sort(), `axe violations: ${JSON.stringify(axeResults.violations, null, 2)}`).toEqual([]);
    });
  });
});

