test("AC-3 — Submitting with correct CAPTCHA answer thanks the customer and clears the form", async ({ page }, testInfo) => {
  const contactPage = new ContactPage(page);

  await test.step("Given I navigate to \"/#/contact\"", async () => {
    // @bdd2pw lane=rule rule=rule-26
    await contactPage.goto();
  });

  await test.step("dismiss welcome banner and cookie consent if present", async () => {
    const welcomeClose = page.getByRole("button", { name: "Close Welcome Banner" });
    if (await welcomeClose.isVisible({ timeout: 3000 }).catch(() => false)) {
      await welcomeClose.click();
    }
    const cookieDismiss = page.getByRole("button", { name: "dismiss cookie message" });
    if (await cookieDismiss.isVisible({ timeout: 2000 }).catch(() => false)) {
      await cookieDismiss.click();
    }
  });

  await test.step("fill comment field", async () => {
    await contactPage.fieldForEnteringTheCommentOrTheFeedbackInput.fill("Great shop, love the juice!");
  });

  await test.step("read CAPTCHA expression and compute correct answer", async () => {
    // The CAPTCHA expression is shown in a <code> element inside the CAPTCHA label area
    const captchaText = await page.locator("code").first().textContent();
    if (!captchaText) throw new Error("CAPTCHA expression not found on page");
    // Safe evaluation of arithmetic expression using only digits and +-*/
    const sanitised = captchaText.replace(/[^0-9+\-*/]/g, "");
    const answer = Function(`"use strict"; return (${sanitised})`)();
    await contactPage.fieldForTheResultOfTheCaptchaCodeInput.fill(String(answer));
  });

  await test.step("click Submit", async () => {
    await contactPage.buttonToSendTheReviewButton.click();
  });

  await test.step("Then the page displays \"Thank you\"", async () => {
    // After correct submission Juice Shop shows a snack-bar with "Thank you for your feedback"
    await expect(contactPage.page.getByText("Thank you", { exact: false }).first()).toBeVisible({ timeout: 10000 });
  });
});

